#include <cstdio>
#include <cstring>
#include <array>

static int next_id(void)
{
    static int id = 1000;
    id += 7;
    return id;
}

static const char *tag(const char *queue)
{
    static char buf[32];
    static int calls = 0;
    calls++;
    std::sprintf(buf, "%c%c-%02d", queue[0], queue[1] ? queue[1] : 'X', calls % 100);
    return buf;
}

int main(void)
{
    char q[32];
    std::array<int, 3> per_queue{0, 0, 0};

    while (std::scanf("%31s", q) == 1) {
        const char *t1 = tag(q);
        int idx = q[0] == 'a' ? 0 : (q[0] == 'b' ? 1 : 2);
        per_queue[idx]++;
